// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/healthz", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/resolve", wrapper.ResolveRef)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/images/{digest}", wrapper.GetImage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/ancestry", wrapper.GetAncestry)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/descendants", wrapper.GetDescendants)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/query", wrapper.RunQuery)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/query/graph", wrapper.GetQueryGraph)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/stale", wrapper.GetStale)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/roots", wrapper.GetRoots)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/summary", wrapper.GetSummary)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/overview", wrapper.GetOverview)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/status", wrapper.GetStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/outline", wrapper.GetOutline)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/search", wrapper.Search)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/map", wrapper.GetMap)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/cleanup", wrapper.GetCleanup)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/cleanup/lifecycle", wrapper.GetLifecycles)

	return m
}

